CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE tenants(id TEXT PRIMARY KEY, name TEXT NOT NULL, timezone TEXT NOT NULL DEFAULT 'Asia/Riyadh', status TEXT NOT NULL DEFAULT 'setup' CHECK(status IN ('setup','active','suspended')), created_at TEXT NOT NULL);
CREATE TABLE users(id TEXT PRIMARY KEY, tenant_id TEXT REFERENCES tenants(id), email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('provider','admin','supervisor','sales','marketing','services','reader')), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, CHECK((role='provider' AND tenant_id IS NULL) OR (role!='provider' AND tenant_id IS NOT NULL)));
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),csrf TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE session_activity(token_hash TEXT PRIMARY KEY REFERENCES sessions(token_hash) ON DELETE CASCADE, issued_at BIGINT NOT NULL, last_seen_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS retention_holds(entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, reason TEXT NOT NULL, held_until TEXT, created_at TEXT NOT NULL, PRIMARY KEY(entity_type,entity_id));
CREATE TABLE rate_limits(key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE requests(id TEXT PRIMARY KEY,reference TEXT NOT NULL UNIQUE,operation_key TEXT NOT NULL UNIQUE,payload_hash TEXT NOT NULL,name TEXT NOT NULL,company TEXT NOT NULL,phone TEXT NOT NULL,country TEXT NOT NULL,activity TEXT NOT NULL,email TEXT NOT NULL,service TEXT NOT NULL,need TEXT NOT NULL,source TEXT NOT NULL,contact_consent TEXT NOT NULL,marketing_consent INTEGER NOT NULL,consented_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'new',owner_id TEXT NOT NULL REFERENCES users(id),quote TEXT NOT NULL DEFAULT '',payment_reference TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE provider_opportunities(id TEXT PRIMARY KEY,request_id TEXT NOT NULL UNIQUE REFERENCES requests(id),owner_id TEXT NOT NULL REFERENCES users(id),stage TEXT NOT NULL DEFAULT 'new');
CREATE TABLE projects(id TEXT PRIMARY KEY,request_id TEXT NOT NULL UNIQUE REFERENCES requests(id),tenant_id TEXT REFERENCES tenants(id),name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'requirements',owner_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE milestones(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),title TEXT NOT NULL,deliverable TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'pending',feedback TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL);
CREATE TABLE contacts(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),name TEXT NOT NULL,phone TEXT NOT NULL,tags TEXT NOT NULL DEFAULT '',marketing_consent INTEGER NOT NULL DEFAULT 0,consent_source TEXT NOT NULL DEFAULT '',consented_at TEXT,withdrawn_at TEXT,created_at TEXT NOT NULL, UNIQUE(tenant_id,phone), UNIQUE(id,tenant_id));
CREATE TABLE opportunities(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),contact_id TEXT NOT NULL,owner_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,stage TEXT NOT NULL DEFAULT 'new',value_minor INTEGER NOT NULL DEFAULT 0 CHECK(value_minor>=0),currency TEXT NOT NULL,reason TEXT NOT NULL DEFAULT '',follow_up TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL, FOREIGN KEY(contact_id,tenant_id) REFERENCES contacts(id,tenant_id));
CREATE TABLE tasks(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),owner_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,due_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL);
CREATE TABLE channels(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),phone_id TEXT NOT NULL UNIQUE,token_env TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'unverified' CHECK(status IN ('unverified','verified','disconnected')),verified_at TEXT, UNIQUE(id,tenant_id));
CREATE TABLE conversations(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),contact_id TEXT NOT NULL,channel_id TEXT NOT NULL,owner_id TEXT REFERENCES users(id),status TEXT NOT NULL DEFAULT 'open',close_reason TEXT NOT NULL DEFAULT '',last_inbound INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL, UNIQUE(id,tenant_id),UNIQUE(channel_id,contact_id), FOREIGN KEY(contact_id,tenant_id) REFERENCES contacts(id,tenant_id), FOREIGN KEY(channel_id,tenant_id) REFERENCES channels(id,tenant_id));
CREATE TABLE messages(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,conversation_id TEXT NOT NULL,provider_id TEXT UNIQUE,operation_key TEXT,author_id TEXT REFERENCES users(id),direction TEXT NOT NULL CHECK(direction IN ('in','out','note')),body TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(tenant_id,operation_key), FOREIGN KEY(conversation_id,tenant_id) REFERENCES conversations(id,tenant_id));
CREATE TABLE webhook_events(id TEXT PRIMARY KEY,payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,error TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE notifications(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,entity_id TEXT NOT NULL,read INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE audit(id TEXT PRIMARY KEY,tenant_id TEXT REFERENCES tenants(id),actor_id TEXT REFERENCES users(id),action TEXT NOT NULL,entity_id TEXT NOT NULL,detail TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE content(key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX contacts_scope ON contacts(tenant_id,name);
CREATE INDEX opportunities_scope ON opportunities(tenant_id,owner_id,stage);
CREATE INDEX conversations_scope ON conversations(tenant_id,owner_id,status);
CREATE INDEX messages_scope ON messages(tenant_id,conversation_id,created_at);
CREATE INDEX audit_scope ON audit(tenant_id,created_at);
INSERT INTO schema_migrations VALUES(1,strftime('%Y-%m-%dT%H:%M:%SZ','now'));
